  'suggestions.comprendre.1_creer_gamme_equipement': { one: '<b>S1 · Creare un piano</b>: attrezzatura seguita senza alcun piano attivo, almeno {n} guasto con la stessa causa nel periodo.', other: '<b>S1 · Creare un piano</b>: attrezzatura seguita senza alcun piano attivo, almeno {n} guasti con la stessa causa nel periodo.' },
  'suggestions.comprendre.2_revoir_preventif_equipement': { one: '<b>S2 · Rivedere la manutenzione preventiva</b>: attrezzatura il cui piano seguito ha già avuto una visita; almeno {n} guasto con la stessa causa nel periodo, dopo la prima visita. Da esaminare: il piano non dice quali guasti previene.', other: '<b>S2 · Rivedere la manutenzione preventiva</b>: attrezzatura il cui piano seguito ha già avuto una visita; almeno {n} guasti con la stessa causa nel periodo, dopo la prima visita. Da esaminare: il piano non dice quali guasti previene.' },
  'suggestions.comprendre.3_anomalies_repetees_gamme': '<b>S3 · Anomalie ripetute</b>: piano seguito con un\'anomalia ad almeno 2 delle ultime 4 visite.',
  'suggestions.comprendre.4_allonger_gamme_depuis_format_2': { one: '<b>S4 · Allungare un piano</b>: piano seguito di un\'attrezzatura con criticità B o C (mai A); almeno {n} visita di seguito senza anomalie (contate dal passaggio al formato 2, il {date}) e nessun guasto dell\'attrezzatura dalla prima di queste visite. Le verifiche di legge non vengono mai suggerite.', other: '<b>S4 · Allungare un piano</b>: piano seguito di un\'attrezzatura con criticità B o C (mai A); almeno {n} visite di seguito senza anomalie (contate dal passaggio al formato 2, il {date}) e nessun guasto dell\'attrezzatura dalla prima di queste visite. Le verifiche di legge non vengono mai suggerite.' },
  'suggestions.comprendre.4_allonger_gamme_gamme': { one: '<b>S4 · Allungare un piano</b>: piano seguito di un\'attrezzatura con criticità B o C (mai A); almeno {n} visita di seguito senza anomalie e nessun guasto dell\'attrezzatura dalla prima di queste visite. Le verifiche di legge non vengono mai suggerite.', other: '<b>S4 · Allungare un piano</b>: piano seguito di un\'attrezzatura con criticità B o C (mai A); almeno {n} visite di seguito senza anomalie e nessun guasto dell\'attrezzatura dalla prima di queste visite. Le verifiche di legge non vengono mai suggerite.' },
  'suggestions.comprendre.apres_decision_ignoree_traitee': '<b>Dopo una decisione</b> (ignorato o gestito) contano solo gli eventi successivi: il suggerimento torna se raggiungono di nuovo la soglia.',
