  'suggestions.comprendre.equipement_suivi_actif_pas': '<b>Attrezzatura seguita</b>: attiva e non dismessa. <b>Piano seguito</b>: attivo, a data o a contatore (mai a soglia), di un\'attrezzatura seguita.',
